def error_budget(total_events, good_events, slo_target):
    if total_events <= 0 or not 0 <= good_events <= total_events or not 0 < slo_target <= 1:
        raise ValueError('INVALID_SLI_INPUT')
    allowed = total_events * (1 - slo_target)
    bad = total_events - good_events
    return {'allowed_bad': allowed, 'observed_bad': bad, 'consumption': bad / allowed if allowed else 0}
